// SDF
float sdCircle( vec2 p, float r ) {
    return length(p) - r;
}

// 效果一
vec4 effect_1(vec2 uv) {
    float c = length(uv);
    c = abs(sin(c * 4.0 - iTime) / 8.0);
    c = smoothstep(0.0, 0.15, c); // 限制范围

    return vec4(vec3(1.0 - c), 1.0);
}

// 效果二
vec4 effect_2(vec2 uv) {
    vec3 color = vec3(1.0, 2.0, 4.0);

    float c = length(uv);
    // c = sin(c * 2.0 - iTime); // 效果一
    c = abs(sin(c * 2.0 - iTime) / 3.0); // 效果二

    c = 0.0125 / c; // 反函数， c值越小，结果越大
    color *= c;

    return vec4(color, 1.0);

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    float ratio = iResolution.x / iResolution.y;

    vec2 center = vec2(0.5, 0.5); // 中心位置

    uv -= center; // 居中
    uv *= 2.0; // 归一化
    uv.x *= ratio;

    // 扰动
    vec2 st = uv;
    st = ceil(st * 10.0) / 10.0; // 像素化

    uv *= texture(iChannel0, st).r; // 扰动 uv


    // Output to screen
    fragColor = effect_2(uv);
}
